import{_ as t,a,o,a6 as d}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Catalog Products — Mass Delete","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-product-mass-delete","title":"Mass Delete Catalog Products","description":"Deletes a batch of catalog products in one call. Ids that do not exist are skipped without an error, and `deleted` lists only the ones actually removed.","query":"curl -X POST \\"https://your-domain.com/api/admin/catalog/products/mass-delete\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\n    \\"indices\\": [12, 18]\\n  }\'\\n","variables":"{\\n  \\"indices\\": [12, 18]\\n}\\n","response":"{\\n  \\"id\\": 1,\\n  \\"deleted\\": [12, 18],\\n  \\"message\\": \\"Products deleted successfully.\\"\\n}\\n","commonErrors":[{"error":"Bad Request (400)","cause":"Empty or malformed `indices` array","solution":"Send a non-empty array of integers"},{"error":"Forbidden (403)","cause":"Admin role lacks `catalog.products.delete`","solution":"Grant the permission to the admin role"},{"error":"Server Error (500)","cause":"Underlying delete threw an exception (mirrors monolith behaviour)","solution":"Investigate the failing ID — usually a FK constraint violation"}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products/mass-delete.md","filePath":"api/rest-api/admin/catalog/products/mass-delete.md","lastUpdated":1787290888000}'),r={name:"api/rest-api/admin/catalog/products/mass-delete.md"};function s(n,e,i,l,c,h){return o(),a("div",null,e[0]||(e[0]=[d('<h1 id="catalog-products-—-mass-delete" tabindex="-1">Catalog Products — Mass Delete <a class="header-anchor" href="#catalog-products-—-mass-delete" aria-label="Permalink to &quot;Catalog Products — Mass Delete&quot;">​</a></h1><p>Deletes a batch of catalog products in a single call. Mirrors <strong>Catalog → Products → Mass Delete</strong> in the Bagisto admin panel.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/products/mass-delete</code></td><td>POST</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>indices</code></td><td>int[]</td><td>yes</td><td>Non-empty array of product IDs. Non-existent IDs are silently skipped.</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>200 OK</code></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Always <code>1</code>. This is an action result, not a record — ignore it.</td></tr><tr><td><code>deleted</code></td><td>int[]</td><td>The ids that were actually removed.</td></tr><tr><td><code>message</code></td><td>string</td><td>Translated confirmation.</td></tr></tbody></table><p><strong><code>deleted</code> is not an echo of <code>indices</code>.</strong> Ids that do not exist are dropped silently, so sending <code>[1403, 999999]</code> returns <code>deleted: [1403]</code>. Compare the two lists to find out what was skipped — nothing else reports it.</p><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><ul><li><strong>Best effort, no transaction.</strong> The batch does not roll back if one id fails partway through; ids processed before the failure stay deleted.</li><li><strong>Configurable variants cascade</strong> with their parent, so a parent id can remove more rows than you listed.</li><li><strong>Order history is unaffected</strong> — order items keep their product snapshot.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Detail</th></tr></thead><tbody><tr><td><code>400</code></td><td><code>The indices field is required and must be a non-empty array.</code></td></tr><tr><td><code>401</code></td><td><code>Unauthenticated.</code></td></tr><tr><td><code>403</code></td><td><code>You do not have permission to manage products.</code> — token lacks <code>catalog.products.delete</code></td></tr></tbody></table><p>Note the validation failures here are <code>400</code>, not the <code>422</code> used by the single-product create and update endpoints.</p>',15)]))}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
